#!/bin/bash

# calling $RANDOM generates an integer number between 0 and 32767 by default
# echo $(($RANDOM%($max-$min+1)+$min))

# The -i option of shuf specifies the input range.
# The generated numbers are randomly selected from the specified range.
# The -n option specifies the number of random numbers that must be generated by shuf.
# In our example, shuf produces only one random number because we pass -n 1 to shuf.
# shuf –i $min-$max –n 1
random_dependencies="
shuf
"

random_int() {
    local lowerLimit=${1}
    local upperLimit=${2}
    local amount=${3}
    local defaultAmount=1

    if [ -z ${3} ]
    then
        amount=${defaultAmount}
    fi

    shuf –i ${lowerLimit}-${upperLimit} –n ${amount}
}
